// programme row-level security — generated by `pnpm gen:migration` (02-architecture §4, 04-testing §3).
// A programme is the client's own grouping, so a client user sees its own client's programmes.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  inActorTransaction,
  migrateUp,
  programme,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
let testDb: TestDatabase;
let database: Database;

const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(programme)).map((r) => r.name).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await inActorTransaction(database.db, staff, async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx.insert(programme).values([
      { id: randomUUID(), clientId: clientA, name: 'Programme 1' },
      { id: randomUUID(), clientId: clientB, name: 'Programme 2' },
    ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every programme', async () => {
  expect(await visibleTo(staff)).toEqual(['Programme 1', 'Programme 2']);
});

it("a client user sees only its own client's programmes", async () => {
  expect(await visibleTo(userOfA)).toEqual(['Programme 1']);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client user cannot create programmes', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(programme).values({ id: randomUUID(), clientId: clientA, name: 'Programme 3' }),
    ),
  ).rejects.toThrow();
});

it('a programme name is unique within its client', async () => {
  await expect(
    inActorTransaction(database.db, staff, (tx) =>
      tx.insert(programme).values({ id: randomUUID(), clientId: clientA, name: 'Programme 1' }),
    ),
  ).rejects.toThrow();
});
